-- 004: 岗位职责/任职要求英文字段 + 存量全量回填
-- 与 002/003 同模式：可重复执行（幂等）。
-- responsibilities_en / requirements_en 存 JSON 字符串数组，与中文列同构；前台解析方式一致。

ALTER TABLE job_publications
  ADD COLUMN IF NOT EXISTS responsibilities_en TEXT,
  ADD COLUMN IF NOT EXISTS requirements_en TEXT;

