UPDATE job_publications SET responsibilities_en = '["Administrative, coordination, and support role for technical teams; whether it involves project management to be confirmed in the detailed JD.\nAdvance technical solution design, assembly, and validation for the technical administration and R&D support direction\nIterate on team experiment/R&D processes and accumulate reusable solutions and documentation"]', requirements_en = '["Administrative coordination, documentation, and R&D support skills\nResearch institution or hard-tech company experience preferred"]' WHERE public_job_code = 'QJ-26-0063';
UPDATE job_publications SET responsibilities_en = '["Develop high-bandwidth, low-latency data communication between GPUs and FPGA/SoC or high-speed acquisition devices.\nDesign and optimize PCIe, DMA, memory mapping, asynchronous transfer, and multi-buffering data paths.\nOwn high-speed camera data ingestion, cache management, real-time GPU processing, and result return.\nWork with FPGA, hardware, and algorithm teams to define interface specifications and complete hardware-software joint debugging.\nDiagnose and resolve insufficient throughput, data loss, memory bottlenecks, and processing latency issues."]', requirements_en = '["Project experience in GPU computing, high-speed data acquisition, or heterogeneous computing.\nProficient in C/C++, Python, and Linux system development.\nFamiliar with GPU parallel programming, memory management, asynchronous execution, and performance optimization.\nFamiliar with PCIe, DMA, shared memory, memory mapping, and cache coherence.\nExperience in joint development of GPUs with FPGA/SoC or PCIe acquisition cards.\nStrong English technical documentation reading and writing skills."]' WHERE public_job_code = 'QJ-26-0065';
UPDATE job_publications SET responsibilities_en = '["Build and maintain the neutral-atom quantum computing platform, including optical tweezer arrays, atom cooling, and trapping systems.\nOptimize initialization, control, and readout performance of atomic qubits, improving coherence times and fidelities.\nDesign and build complex optical systems for precise, stable control of multi-wavelength lasers.\nIntegrate and debug quantum control electronics with the electronics team; support error correction and scaling.\nParticipate in experimental data analysis and write technical documentation and academic papers."]', requirements_en = '["MSc or above in atomic/molecular physics, optics, quantum physics, or related majors; PhD preferred.\nFamiliar with ultracold-atom experimental techniques; hands-on experience building or maintaining complex optical and vacuum systems.\nExpert with neutral-atom control techniques such as optical tweezer arrays, magneto-optical traps, and Rydberg excitation.\nFamiliar with laser stabilization, AOMs, EOMs, and other optoelectronic device usage and alignment.\nProficient with LabVIEW, Python, or MATLAB for experiment automation and data processing.\nGood English reading/writing; able to independently read frontier literature and reproduce experimental schemes."]' WHERE public_job_code = 'QJ-26-0066';
UPDATE job_publications SET responsibilities_en = '["Own vacuum-space optical system design, using Zemax for ray simulation, tolerance analysis, and stray-light analysis.\nIndependently assemble and align precision optical platforms.\nHandle selection of lasers, polarization optics, high-performance lenses, and other components, including supplier technical communication.\nWrite optical system design reports, alignment procedures, test standards, and maintenance manuals.\nWork with mechanical engineers on opto-mechanical design and help the physics team optimize optical performance."]', requirements_en = '["MSc or above in physics, optics, optical engineering, or related majors.\nProficient with Zemax; able to independently design lens groups, calibrate aberrations, and simulate complex systems.\nExperience designing and building free-space optical paths; familiar with laser collimation, polarization control, and interferometry.\nSolid optical theory foundations; familiar with Gaussian beam propagation and Fourier optics.\nExcellent logical thinking and hands-on skills; able to independently resolve optical alignment issues."]' WHERE public_job_code = 'QJ-26-0067';
UPDATE job_publications SET responsibilities_en = '["Own end-to-end R&D project management, including initiation, task breakdown, scheduling, progress tracking, and risk control.\nCoordinate resources and schedules across experiment, hardware, algorithm, and control teams to hit milestones.\nLead the R&D roadmap and report overall progress to management regularly.\nSupport application and execution management of government programs and research projects."]', requirements_en = '["MSc or above in a STEM field; physics, electronics, optics, or quantum information preferred.\n3+ years of hard-tech R&D project management experience; quantum, semiconductor, precision instrument, or aerospace background preferred.\nAble to understand engineers'' technical language and communicate effectively with technical experts.\nStrong communication, coordination, logical thinking, and execution."]' WHERE public_job_code = 'QJ-26-0068';
UPDATE job_publications SET responsibilities_en = '["Participate in quantum algorithm design and circuit compilation for the neutral-atom platform, optimizing for Rydberg gates and optical tweezer arrays.\nDevelop quantum simulators and numerical tools to validate many-body dynamics, gate fidelities, and decoherence effects.\nApply machine learning or data-driven methods to analyze intensity images, noise spectra, and gate errors; optimize control parameters.\nTrack frontier literature and explore quantum-AI intersections in cold-atom systems.\nWrite high-performance scientific computing code in Python, Julia, or C++; maintain algorithm libraries and simulation platforms."]', requirements_en = '["MSc or above in physics, quantum information, computer science, mathematics, or related majors.\nSolid foundations in quantum mechanics and quantum information; familiar with gates, circuits, entanglement, and open quantum systems.\nProficient with Python and scientific computing tools such as NumPy, SciPy, PyTorch, and JAX.\nExperience developing algorithms such as QAOA, VQE, Shor, or quantum random walks, or in quantum compilation optimization.\nAble to independently read English literature and implement or improve algorithms."]' WHERE public_job_code = 'QJ-26-0069';
UPDATE job_publications SET responsibilities_en = '["Lead the construction and innovative research of an internationally frontier neutral-atom quantum computing platform.\nDrive research on atom arrays, quantum gate control, error correction hardware, and novel quantum gates.\nBuild and continuously raise the research capacity and output of the quantum computing experimental platform."]', requirements_en = '["PhD or above in physics, quantum information, computer science, electronic information, or related majors.\nAt least 3 years of experience in quantum computing or neutral atoms.\nOutstanding research track record with high-level original results."]' WHERE public_job_code = 'QJ-26-0070';
UPDATE job_publications SET responsibilities_en = '["Own theoretical research and numerical simulation of quantum error correction; design efficient codes for the neutral-atom platform.\nBuild quantum noise models; evaluate thresholds, resource overhead, and performance of correction schemes on real hardware.\nParticipate in co-optimization of error correction and control; explore hardware-feedback-oriented decoders.\nTrack frontier progress and land algorithms in real control systems with the experimental team."]', requirements_en = '["MSc or above in quantum physics, quantum information, mathematics, communication engineering, or related majors.\nSolid grasp of linear algebra, probability, information theory, and quantum mechanics.\nProficient with Python, MATLAB, or C++ for numerical simulation and data processing.\nProject experience with surface codes, color codes, stabilizer codes, graph codes, quantum noise, LDPC, or Polar codes preferred.\nStrong paper reading and reproduction skills."]' WHERE public_job_code = 'QJ-26-0071';
UPDATE job_publications SET responsibilities_en = '["Design, implement, and maintain the quantum compiler core pipeline, including IR, optimization passes, and hardware-specific lowering.\nDevelop atom movement scheduling algorithms under physical constraints such as Rydberg blocking and partitioned architectures.\nCollaborate with physicists and hardware engineers on compilation strategies that improve fidelity, speed, and resource utilization.\nBuild post-compilation circuit analysis, profiling, simulation, and verification tools.\nResearch novel compilation techniques and optimization methods for neutral-atom hardware."]', requirements_en = '["MSc or above in computer science, compilers, systems programming, or related majors.\nFoundations in compiler design, algorithms, and systems programming.\n5+ years of software development experience, including 2+ years in compilers, DSLs, or systems programming.\nExpert in at least one of C/C++, Rust, or Zig; familiar with Python.\nUnderstands SDLC, Git, code review, testing, CI/CD, profiling, and debugging.\nStrong English technical documentation reading and writing skills."]' WHERE public_job_code = 'QJ-26-0072';
UPDATE job_publications SET responsibilities_en = '["Own hardware and embedded design of laser control systems; contribute to product function, performance, and architecture design.\nPlan laser control circuits from product requirements; solve noise interference and improve frequency and power stability.\nCollaborate with optical engineers to implement and optimize laser-related circuits.\nComplete component selection, schematic design, and PCB design; help resolve production and field issues.\nWrite hardware design documents, test specifications, and BOMs."]', requirements_en = '["Bachelor or above in electronic science, electronic information engineering, automation, or related majors.\n3+ years of analog circuit design experience; laser or precision instrument control circuit experience preferred.\nMaster low-noise amplification, filtering, PID, and other analog design; familiar with Altium Designer, FPGA, and bus protocols.\nEngineering mindset, problem diagnosis skills, and teamwork."]' WHERE public_job_code = 'QJ-26-0073';
UPDATE job_publications SET responsibilities_en = '["Participate in BSP development, boot adaptation, peripheral driver development, and low-level software maintenance across the Zynq family.\nOwn Zynq PS/PL co-development: AXI bus interaction, DMA transfers, interrupt management, shared memory, and high-speed data channels.\nInterface with FPGA, hardware design, and control algorithm teams to advance interface specifications and delivery.\nConduct HIL simulation, power testing, and full-system integration; diagnose data anomalies, driver timing, throughput, and packet loss issues.\nMaintain low-level interface specs, driver design docs, functional test cases, and code versions."]', requirements_en = '["Zynq platform project experience; Zynq UltraScale+ MPSoC or similar SoC mass-production experience preferred.\nProficient in C/C++ and Python; bare-metal and embedded Linux development.\nUnderstands BSP, bootloaders, device trees, peripheral drivers, interrupts, DMA, cache coherence, and memory mapping.\nUnderstands Zynq PS/PL co-design, AXI buses, register interfaces, and high-speed data paths.\nBoard bring-up, JTAG, oscilloscope, or logic analyzer debugging experience.\nFamiliar with PYNQ Overlay deployment and IP driver validation; strong English technical documentation skills."]' WHERE public_job_code = 'QJ-26-0074';
UPDATE job_publications SET responsibilities_en = '["Own mechanical structure and thermal management design for laser products; contribute to function, performance, and overall architecture.\nPlan laser mechanical structures, optical component fixtures, and quantum platform tooling to guarantee precision and stability.\nResolve heat dissipation, precision drift, and stability issues through thermal simulation and cooling design.\nWork with optical engineers on structure/fixture-to-optical-path fit and optimization.\nComplete part selection, 2D/3D drawings, process planning, design docs, test specs, and BOMs."]', requirements_en = '["Bachelor or above in mechanical design & manufacturing, mechanical engineering, precision instruments, or mechatronics.\n3+ years of mechanical design experience; laser, precision instrument, thermal simulation, or quantum platform tooling experience preferred.\nMaster mechanical, thermal, and low-noise structural design; familiar with precision positioning fixtures.\nProficient with SolidWorks, AutoCAD, COMSOL, ANSYS, or Icepak.\nEngineering mindset, problem-solving skills, and cross-team collaboration."]' WHERE public_job_code = 'QJ-26-0075';
UPDATE job_publications SET responsibilities_en = '["Testing"]', requirements_en = '["PhD degree"]' WHERE public_job_code = 'QJ-26-0076';
UPDATE job_publications SET responsibilities_en = '["Quantum measurement and control engineering"]' WHERE public_job_code = 'QJ-26-0077';
